head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > getInfo]<br/>DataMap 모듈과 Key 의 세부 정보를 객체로 반환합니다.",
    "validation" : [
        "반환값으로 DataMap 모듈과 Key 의 세부 정보를 JSON 형식의 객체로 반환합니다.",
        "반환된 객체의 dataMapInfo 속성값으로 DataMap 모듈의 세부 정보를 JSON 형식의 객체로 갖습니다.",
        "반환된 객체의 keyInfo 속성값으로 Key 의 ID 값을 Key 로, Key 의 정보를 객체로 갖습니다.",
        "Key 정보 객체는 Key 에 설정된 속성들이 '속성명:속성값' 형태의 Key-Value 쌍으로 구성됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataMap();

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');
}   



scwin.btn_getInfo_onclick = function (e) {
    let rtn = target1.getInfo();

	wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("result.dataMapInfo.id : " + rtn.dataMapInfo.id);
    wf_body_bottom.getObj("scwin").setReturnValue("result.keyInfo.key1.id  : " + rtn.keyInfo.key1.id);
    wf_body_bottom.getObj("scwin").setReturnValue("result.keyInfo.key2.id  : " + rtn.keyInfo.key2.id);
    wf_body_bottom.getObj("scwin").setReturnValue("result.keyInfo.key3.id  : " + rtn.keyInfo.key3.id);
    wf_body_bottom.getObj("scwin").setReturnValue("result.keyInfo.key4.id  : " + rtn.keyInfo.key4.id);
};
